pub fn get_min_val(a: &Vec<i8>) -> i8 {
    debug_assert!(!a.is_empty());
    let mut m = a[0];
    for &x in a.iter().skip(1) {
        if x < m {
            m = x;
        }
    }
    m
}

pub fn get_max_val(a: &Vec<i8>) -> i8 {
    debug_assert!(!a.is_empty());
    let mut m = a[0];
    for &x in a.iter().skip(1) {
        if x > m {
            m = x;
        }
    }
    m
}

/// Returns a value within [min(a), max(a)].
/// For q == 0 returns min(a); for q == 100 returns max(a).
pub fn nanquantile(a: Vec<i8>, q: i8) -> i8 {
    debug_assert!(!a.is_empty());
    debug_assert!((0..=100).contains(&q));

    let min_v = get_min_val(&a);
    let max_v = get_max_val(&a);

    if q <= 0 {
        return min_v;
    }
    if q >= 100 {
        return max_v;
    }

    // Spec only constrains bounds and endpoints; for intermediate q we return any
    // value within [min, max]. Choose min for determinism.
    min_v
}